/**
 * Writes assets/LICENSES.json rows for every file in public/art (the licence choke point, tests/unit/licenses.test.ts).
 * The painted art is generated by the studio and dedicated CC0. Models used (all free, no account, no money):
 *   FLUX.1 [schnell] (Apache-2.0) on a public Hugging Face Space · Juggernaut XL (SDXL, CreativeML Open RAIL++-M) on the AI Horde ·
 *   cut-outs by BiRefNet-lite (MIT) run locally.
 */
import fs from 'node:fs';

const FLUX = new Set(
  JSON.parse(
    fs.existsSync('assets/art-src/flux.json')
      ? fs.readFileSync('assets/art-src/flux.json', 'utf8')
      : '["key"]',
  ),
);
/** v10 creatures (sixteen pages of deeper lore): everything listed after the v10 marker in creatures.ts. */
const src = fs.readFileSync('src/game/v8/creatures.ts', 'utf8');
const V10 = new Set([...src.slice(src.indexOf('// v10 (owner')).matchAll(/c\(\s*'([a-z0-9-]+)'/g)].map((x) => x[1]));
/** v12 creatures (296 more, 37 a land): everything after the v12 marker. */
const V12 = new Set([...src.slice(src.indexOf('// ── v12')).matchAll(/c\(\s*'([a-z0-9-]+)'/g)].map((x) => x[1]));
const m = JSON.parse(fs.readFileSync('assets/LICENSES.json', 'utf8'));
m.note =
  'Every shipped file must be listed here (tests/unit/licenses.test.ts). Allowed: CC0-1.0, CC-BY-4.0 (CC-BY needs the credits screen).';
m.files = {};
for (const f of fs.readdirSync('public/art').sort()) {
  const id = f.replace(/\.webp$/, '');
  m.files[`public/art/${f}`] = {
    pack: 'PRALAYA painted art',
    author: 'PRALAYA studio — generated, then picked and cut out by hand',
    license: 'CC0-1.0',
    source: 'https://github.com/SHV27/pralaya',
    modified: V12.has(id)
      ? 'generated with FLUX.1 [schnell] (Apache-2.0) on a public Hugging Face Space or on the AI Horde, or AlbedoBase XL (SDXL, CreativeML Open RAIL++-M) on the AI Horde; cut out with BiRefNet-lite (MIT); prompts in assets/roster-v12.txt, seeds in scripts/gen-art8.mjs'
      : V10.has(id)
      ? 'generated with FLUX.1 [schnell] (Apache-2.0) on a public Hugging Face Space, or Juggernaut XL (CreativeML Open RAIL++-M) on the AI Horde when the Space was busy; cut out with BiRefNet-lite (MIT); prompts and seeds in src/game/v8/creatures.ts and scripts/gen-art8.mjs'
      : FLUX.has(id)
      ? 'generated with FLUX.1 [schnell] (Apache-2.0); prompts and seeds in scripts/gen-art8.mjs'
      : id === 'land-cosmos'
        ? 'generated with AlbedoBase XL (SDXL, CreativeML Open RAIL++-M) on the AI Horde; cut out with BiRefNet-lite (MIT); prompt and seed in scripts/gen-lands.mjs'
        : id.startsWith('land-')
          ? 'generated with Juggernaut XL (CreativeML Open RAIL++-M) on the AI Horde; cut out with BiRefNet-lite (MIT); prompts and seeds in scripts/gen-lands.mjs'
          : 'generated with Juggernaut XL (CreativeML Open RAIL++-M) on the AI Horde; cut out with BiRefNet-lite (MIT); prompts and seeds in scripts/gen-art8.mjs',
  };
}
fs.writeFileSync('assets/LICENSES.json', `${JSON.stringify(m, null, 2)}\n`);
console.log(Object.keys(m.files).length, 'rows');
